contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed parameters: caller (actor) and amount to send
    function testFuzz_property(address caller, uint256 amount) public {
        // keep caller non-zero and not the owner to exercise the property
        vm.assume(caller != address(0));
        // bound amount to a reasonable range so we can fund the caller in the test
        amount = bound(amount, 0, 1 ether);

        // fund the contract and the caller so transfers are possible
        // contract starts with 0 balance; fund it from this test contract
        vm.deal(address(this), 1 ether);
        // send some ether into the contract so sendTo can transfer out
        (bool s,) = address(c).call{value: 1 ether}(abi.encodeWithSignature("sendTo(address,uint256)", address(this), uint256(0)));
        // The above will revert on correct contract because owner check prevents non-owner call with amount 0,
        // but we just want the contract to have balance; instead send funds directly
        // Use self-destruct trick: deploy a helper that selfdestructs to c to fund it
        FundSender fs = new FundSender{value: 1 ether}();
        fs.sendTo(address(c));

        // capture balance before the call
        uint256 balBefore = address(c).balance;

        // Ensure caller has enough ETH to attempt a payable call if needed
        vm.deal(caller, amount);

        // If the caller is the owner (deployer of c), call should succeed and may transfer funds.
        // We want to check the universal property: only owner can successfully cause sendTo to transfer out funds.
        // Make the fuzzer supply caller; use vm.prank to impersonate them.
        bool ok;
        vm.prank(caller);
        // try to call sendTo sending 'amount' to the caller itself (a valid non-zero address)
        try c.sendTo(caller, amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule: if caller is not the owner, the call must not succeed in the reference implementation
        // Therefore: for ALL inputs, if caller != owner then c.balance must remain unchanged and/or call must revert.
        // We read the post-call balance and assert that either the call reverted (ok == false) or the balance didn't decrease.
        uint256 balAfter = address(c).balance;

        // Assert the universal property: either the call failed, or (if it succeeded) caller must be the owner.
        // We only have one assertion allowed. Encode the property as: (ok == false) || (caller == address(this))
        // But owner was the deployer (this test contract), because setUp used new C() from this contract.
        // So owner == address(this). We assert that if the call succeeded then caller == owner.
        assertTrue(!ok || caller == address(this));
    }
}

