contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // single test entry: we send some ether to c, then attempt to invoke sendTo
    // parameters:
    // - fund: amount of wei to first fund this test contract so it can forward to c
    // - depositToC: amount of wei to send into c (must be > 0 and <= fund)
    // - receiver: address to pass to c.sendTo (the mutant allows address(0), original rejects)
    // - amountOut: amount of wei to ask c to transfer out

    function run(uint fund, uint depositToC, address receiver, uint amountOut) public payable {
        // fund this contract externally via msg.value; ensure caller provided enough
        require(msg.value == fund, "provide fund as msg.value");

        // we need some balance here to forward into c
        require(fund >= depositToC, "insufficient fund to deposit to c");
        require(depositToC > 0, "must deposit > 0");

        // forward depositToC to c so c has balance to send
        (bool ok,) = address(c).call{value: depositToC}("");
        require(ok, "funding c failed");

        // Preconditions that make the behaviour distinguishing:
        // - caller must be owner of c to pass the first require in sendTo
        //   We can't set msg.sender for c's constructor here; instead require that this contract is the owner
        //   Achieve this by requiring that address(this) equals the owner of c: owner is private, but if this contract
        //   is not owner then c.sendTo will revert on both versions; therefore require we are owner by attempting a benign call
        // Attempting c.sendTo with receiver = address(0) would revert on P; but we need to ensure owner equality.
        // We'll rely on the fact that the test harness will deploy c with owner = address(this).

        // Call the deciding action: try to make c send amountOut to receiver.
        // It will revert on P if receiver == address(0), but succeed on M.
        // We perform the state-changing call as required.
        // If it reverts, solidity will revert the whole transaction; to keep this test contract compiled and checkable by a verifier,
        // we capture the success as a low-level call and observe success boolean.
        (bool success, ) = address(c).call(abi.encodeWithSignature("sendTo(address,uint256)", receiver, amountOut));

        // Final assertion: after the call, c's balance must be unchanged when receiver is the zero address
        // (i.e., original contract P prevents sending to zero so balance stays the same), but mutant M would allow it
        // and decrease c's balance. We express this generally by requiring that if receiver == address(0) then
        // address(c).balance >= depositToC (i.e., no ETH left c had been able to send away).
        // Note: we require depositToC > 0 above, so this comparison is meaningful.
        assert(!(receiver == address(0)) || address(c).balance >= depositToC);
    }

    // allow contract to receive ether when called externally
    receive() external payable {}
}

